using Microsoft.ML;
using Microsoft.ML.Data;

var mlContext = new MLContext(seed: 0);

// Load data
var dataPath = Path.Combine(AppContext.BaseDirectory, "..", "..", "..", "Data", "customers.csv");
var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ',');

// Build training pipeline
var pipeline = mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region))
    .Append(mlContext.Transforms.Concatenate("Features", nameof(CustomerData.Age), nameof(CustomerData.Income), "RegionEncoded", nameof(CustomerData.PurchaseHistory)))
    .Append(mlContext.Transforms.NormalizeMinMax("Features"))
    .Append(mlContext.BinaryClassification.Trainers.SdcaLogisticRegression(
        labelColumnName: "Label", featureColumnName: "Features"));

// Train model
Console.WriteLine("Training churn prediction model...");
var model = pipeline.Fit(dataView);

// Evaluate
var predictions = model.Transform(dataView);
var metrics = mlContext.BinaryClassification.Evaluate(predictions, labelColumnName: "Label");
Console.WriteLine($"Accuracy: {metrics.Accuracy:P2}");
Console.WriteLine($"AUC:      {metrics.AreaUnderRocCurve:P2}");

// Sample prediction
var predEngine = mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(model);
var sample = new CustomerData { Age = 40, Income = 70000, Region = "West", PurchaseHistory = 2 };
var result = predEngine.Predict(sample);
Console.WriteLine($"\nSample: Age=40, Income=70k, Region=West, Purchases=2");
Console.WriteLine($"Prediction: {(result.PredictedLabel ? "Will Churn" : "Won't Churn")} (Probability: {result.Probability:P1})");

// Save model
var modelPath = Path.Combine(AppContext.BaseDirectory, "ChurnModel.zip");
mlContext.Model.Save(model, dataView.Schema, modelPath);
Console.WriteLine($"\nModel saved to {modelPath}");

